#[cfg(test)]
mod tests {
    use std::time::Duration;

    use chrono::Utc;
    use rigorix_engine::capacity_ledger::application::{
        CapacityLedgerService, CapacityLedgerServiceImpl, CommitCapacityInput,
        CommitCapacityOutput, ExposureOutput, ExposureQuery, ReleaseCapacityInput,
        ReleaseCapacityOutput, ReserveCapacityInput, ReserveCapacityOutput,
    };
    use rigorix_engine::capacity_ledger::domain::{
        Exposure, IdempotencyKey, Lease, Reservation, ReservationId, ResourceId, Window,
    };

    fn sample_reservation() -> Reservation {
        Reservation::new(
            ReservationId::new(),
            ResourceId::new("gpu"),
            2,
            Lease::expiring_in(Utc::now(), Duration::from_secs(60)),
            IdempotencyKey::new("k1"),
        )
    }

    fn sample_exposure() -> Exposure {
        Exposure::new(ResourceId::new("gpu"), 10, 1, 2, Window::bounded(60))
    }

    #[test]
    fn test_capacityledgerservice_is_defined() {
        // Use cases are consumed as a boxed trait object by the enforcement seam.
        fn assert_object_safe(_: Option<Box<dyn CapacityLedgerService>>) {}
        assert_object_safe(None);

        // The concrete service satisfies the frozen trait.
        fn assert_impl<T: CapacityLedgerService>() {}
        assert_impl::<CapacityLedgerServiceImpl>();
    }

    #[test]
    fn test_capacityledgerservice_interacts_with_capacityledger() {
        let input = ReserveCapacityInput {
            resource: ResourceId::new("gpu"),
            amount: 2,
            idempotency_key: IdempotencyKey::new("k1"),
            requested_by: Some("step-1".to_string()),
        };
        let json = serde_json::to_string(&input).unwrap();
        assert!(json.contains("\"amount\":2"));
        let round_trip: ReserveCapacityInput = serde_json::from_str(&json).unwrap();
        assert_eq!(round_trip, input);
    }

    #[test]
    fn test_capacityledgerservice_interacts_with_reservation() {
        let reservation = sample_reservation();
        let commit = CommitCapacityInput {
            reservation_id: reservation.id,
        };
        let output = CommitCapacityOutput {
            reservation: reservation.clone(),
            exposure: sample_exposure(),
        };
        assert_eq!(output.reservation.id, commit.reservation_id);

        let json = serde_json::to_string(&output).unwrap();
        let round_trip: CommitCapacityOutput = serde_json::from_str(&json).unwrap();
        assert_eq!(round_trip, output);

        let release = ReleaseCapacityInput {
            reservation_id: reservation.id,
            reason: Some("step failed".to_string()),
        };
        let released = ReleaseCapacityOutput {
            reservation,
            exposure: sample_exposure(),
        };
        assert_eq!(released.reservation.id, release.reservation_id);
    }

    #[test]
    fn test_capacityledgerservice_reserve_output_owns_no_guard() {
        // The service owns the guard. The DTO exposes the snapshot and exposure
        // only, and never a handle on the wire (#1049).
        let output = ReserveCapacityOutput {
            reservation: sample_reservation(),
            exposure: sample_exposure(),
        };
        let json = serde_json::to_string(&output).unwrap();
        assert!(!json.contains("guard"));
        let round_trip: ReserveCapacityOutput = serde_json::from_str(&json).unwrap();
        assert_eq!(round_trip, output);
    }

    #[tokio::test]
    async fn service_drop_releases_outstanding_guards() {
        use std::sync::Arc;

        use rigorix_engine::capacity_ledger::domain::{ResourceSpec, Window};
        use rigorix_engine::capacity_ledger::infrastructure::InProcessLedger;
        use rigorix_engine::capacity_ledger::interfaces::CapacityLedger;

        let ledger = Arc::new(InProcessLedger::new());
        let resource = ResourceId::new("drop-gpu");
        ledger
            .declare_resource(ResourceSpec::new(
                resource.clone(),
                "drop-gpu".to_string(),
                4,
                Window::bounded(60),
            ))
            .await
            .unwrap();

        let service = CapacityLedgerServiceImpl::new(ledger.clone());
        let output = service
            .reserve(ReserveCapacityInput {
                resource: resource.clone(),
                amount: 3,
                idempotency_key: IdempotencyKey::new("drop-k1"),
                requested_by: None,
            })
            .await
            .unwrap();
        assert_eq!(output.exposure.outstanding, 3);

        // Service-lifetime RAII: dropping the service drops the owned guards,
        // whose Drop dispatches a release onto the captured runtime.
        drop(service);
        tokio::time::sleep(Duration::from_millis(150)).await;

        let exposure = ledger.exposure(&resource).await.unwrap();
        assert_eq!(exposure.outstanding, 0);
        assert_eq!(exposure.committed, 0);
    }

    #[test]
    fn test_capacityledgerservice_interacts_with_exposure() {
        let query = ExposureQuery {
            resource: ResourceId::new("gpu"),
        };
        assert!(serde_json::to_string(&query).unwrap().contains("gpu"));

        let output = ExposureOutput {
            exposure: sample_exposure(),
        };
        assert_eq!(output.exposure.committed, 1);
        assert_eq!(output.exposure.outstanding, 2);
    }
}
